'use strict';
OP.gallery=[
 ['ref_luffy','Monkey D. Luffy','tripulacion','Capitán de los Sombrero de Paja. Su sombrero y su sueño marcan el comienzo del viaje.'],['ref_zoro','Roronoa Zoro','tripulacion','El espadachín de tres espadas que aspira a llegar a la cima.'],['ref_nami','Nami','tripulacion','Una interpretación de su apariencia de sagas posteriores. La campaña de East Blue conserva su bastón y su vestuario clásico.'],['ref_sanji','Sanji · Diable Jambe','formas','Esta ilustración representa una técnica posterior a East Blue. En la campaña, Sanji pelea con sus patadas clásicas.'],['ref_ace','Portgas D. Ace','aliados','El hermano de Luffy, representado con su sombrero naranja y sus llamas.'],['ref_law','Trafalgar Law','aliados','El capitán de los Piratas de Heart, con su espada y su característico gorro.'],
 ['ref_gear2','Luffy · Gear Second','formas','Una transformación de una etapa posterior del viaje. Ilustración de referencia.'],['ref_gear5','Luffy · Gear Fifth','formas','La forma blanca y sonriente de una etapa muy posterior. Ilustración de referencia.'],['ref_zorowano','Zoro · Wano','formas','Una apariencia de Zoro con el vestuario y las espadas de Wano.'],['ref_sanjiifrit','Sanji · Ifrit Jambe','formas','La representación de Sanji con llamas azules que adjuntaste como referencia.'],['ref_lawawake','Law · Despertar','formas','Una representación avanzada del cirujano de la muerte.'],['ref_shanks','Shanks','aliados','El pirata pelirrojo que confió su sombrero a Luffy.'],
 ['ref_mihawk','Dracule Mihawk','rivales','El espadachín que encarna la meta que Zoro quiere alcanzar.'],['ref_enel','Enel','rivales','La figura del trueno de Skypiea, representada con sus tambores y su báculo.'],['ref_robin','Nico Robin','tripulacion','La arqueóloga de los Sombrero de Paja, con una apariencia de sagas posteriores.'],['ref_chopper','Tony Tony Chopper','tripulacion','El médico de la tripulación, representado con su sombrero azul y sus astas.'],['ref_usopp','Usopp','tripulacion','El tirador con una apariencia posterior a East Blue. En la campaña conserva su pequeño tirachinas.'],['ref_yamato','Yamato','aliados','Una ilustración de Yamato con su kanabo y su vestuario de Wano.']
];
Object.assign(OP.UI,{
 adventureExtras(){const hero=document.querySelector('.hero');if(!hero)return;const s=OP.save,c=OP.characters.find(c=>c.id===s.selected),ch=OP.chapters[s.chapter];hero.insertAdjacentHTML('afterend',`<section class="voyage-panel"><div class="voyage-captain"><canvas width="82" height="90" data-portrait="${c.id}" data-large="true"></canvas><div><small>LISTO PARA ZARPAR</small><strong>${c.name}</strong><span>${c.role} · ${c.weapon}</span></div></div><div class="voyage-next"><small>TU SIGUIENTE DESTINO</small><strong>${ch.title} <span>→</span></strong><span>Jefe: ${ch.boss} · Llega a los 90 segundos</span></div><button class="secondary" id="port-help">Cómo jugar <span>↗</span></button></section>`);document.getElementById('port-help').onclick=()=>this.help();this.paint()},
 crewExtras(){const grid=document.querySelector('.crew-grid');if(!grid)return;grid.querySelectorAll('.crew-card').forEach((el,i)=>{const char=OP.characters[i];el.style.setProperty('--char-accent',char.color);el.querySelector('.crew-body').insertAdjacentHTML('beforeend',`<div class="crew-techniques"><small>TÉCNICA ESPECIAL · E</small><strong>${char.special}</strong><span>Esquiva con Espacio · El ataque principal es automático</span></div>`)});grid.insertAdjacentHTML('afterend','<div class="gallery-invite"><div><small>MÁS ALLÁ DE EAST BLUE</small><h2>Un mundo lleno de leyendas.</h2><p>Explora las 18 ilustraciones y formas de tus referencias.</p></div><button class="primary" id="crew-gallery">Abrir galería <span>→</span></button></div>');document.getElementById('crew-gallery').onclick=()=>this.navigate('gallery')},
 gallery(filter='todos'){this.galleryFilter=filter;const group={todos:'Todos',tripulacion:'Tripulación',aliados:'Aliados',rivales:'Rivales',formas:'Formas'};const list=OP.gallery.filter(a=>filter==='todos'||a[2]===filter);document.getElementById('main').innerHTML=this.header('LA COLECCIÓN DE REFERENCIA','El mundo es mucho más grande.','Tus 18 ilustraciones, integradas en una galería. Las formas y los personajes de otras sagas se muestran aquí; la campaña jugable sigue centrada en East Blue.')+`<div class="gallery-toolbar"><div role="group" aria-label="Filtrar galería">${Object.entries(group).map(([id,label])=>`<button data-gallery-filter="${id}" class="${filter===id?'selected':''}" aria-pressed="${filter===id}">${label}</button>`).join('')}</div><span>${list.length} ILUSTRACIONES</span></div><div class="gallery-grid">${list.map(a=>`<button class="gallery-card" data-gallery="${a[0]}"><canvas width="190" height="200" data-gallery-portrait="${a[0]}"></canvas><small>${group[a[2]].toUpperCase()}</small><strong>${a[1]}</strong><span>Ver personaje ↗</span></button>`).join('')}</div><div class="gallery-invite"><div><small>ARTE APORTADO POR TI</small><h2>De tu prototipo a esta aventura.</h2><p>La portada, la colección y los fotogramas de carrera están integrados en esta versión.</p></div><button class="secondary" id="original-sheet">Ver lámina original</button></div>`;document.querySelectorAll('[data-gallery-filter]').forEach(b=>b.onclick=()=>this.gallery(b.dataset.galleryFilter));document.querySelectorAll('[data-gallery]').forEach(b=>b.onclick=()=>this.galleryDetail(b.dataset.gallery));document.getElementById('original-sheet').onclick=()=>{this.modal(`<div class="eyebrow">TU REFERENCIA ORIGINAL</div><h2 id="modal-title">La colección completa.</h2><img class="original-sheet" src="${OP.assetURL('reference/collection.png')}" alt="Lámina original de 18 personajes chibi de One Piece"><button class="primary" id="sheet-close">Volver a la galería</button>`,true);document.getElementById('sheet-close').onclick=()=>this.close()};this.paint()},
 galleryDetail(id){const item=OP.gallery.find(a=>a[0]===id);if(!item)return;this.modal(`<div class="eyebrow">GALERÍA · ONE PIECE</div><div class="gallery-detail"><canvas width="240" height="260" data-gallery-portrait="${id}"></canvas><div><h2 id="modal-title">${item[1]}</h2><p>${item[3]}</p><small>Ilustración de la referencia que compartiste.</small></div></div><button class="primary" id="gallery-close">Volver a la colección</button>`);this.paint();document.getElementById('gallery-close').onclick=()=>this.close()}
});
const galleryNav=document.createElement('button');galleryNav.className='nav';galleryNav.dataset.page='gallery';galleryNav.textContent='Galería';document.querySelector('.topbar nav').append(galleryNav);
OP.UI.init();OP.Art.loadSprites();
